@startuml

class Driver {
  + id : int
  + name : string
  + isOnSickLeave : boolean
}

class Bus {
  + licencePlate : string
  + isInRepairShop : boolean
}

class BusRoute {
  + routeNumber : int
}

class Shift {
  + shiftType : string
}

class Schedule {
  + date : date
}

BusRoute "1" -- "*" Bus : assigned to
Bus "1" -- "0..*" Schedule : assigned to
Driver "1" -- "*" Schedule : assigned to
BusRoute "1" -- "*" Schedule : has
Shift "1" -- "*" Schedule : part of
Schedule "*" -- "1" Bus : for
Schedule "*" -- "1" Driver : for
Schedule "*" -- "1" BusRoute : on

@enduml

